#
# Structure for table "indicator_definition"
#

CREATE TABLE `indicator_definition` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `indicator_name` varchar(100) NOT NULL COMMENT '指标名称',
  `indicator_code` varchar(50) NOT NULL COMMENT '指标编码，唯一',
  `result_var_name` varchar(50) DEFAULT NULL COMMENT '指标结果变量名，如 taxRate/profitRate',
  `indicator_logic` varchar(500) NOT NULL COMMENT '展示用指标逻辑说明',
  `formula_expression` longtext NOT NULL COMMENT '后端可执行的受限指标公式',
  `task_id` bigint(20) unsigned NOT NULL COMMENT '数据来源任务ID，关联 rpa_task.id',
  `status` int(11) NOT NULL DEFAULT '1' COMMENT '状态：1启用，0停用',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_indicator_definition_code` (`indicator_code`),
  KEY `idx_indicator_definition_task_id` (`task_id`),
  CONSTRAINT `fk_indicator_definition_task` FOREIGN KEY (`task_id`) REFERENCES `rpa_task` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='指标定义表';

#
# Data for table "indicator_definition"
#


#
# Structure for table "indicator_quota_rule_indicator"
#

CREATE TABLE `indicator_quota_rule_indicator` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `quota_rule_id` bigint(20) unsigned NOT NULL COMMENT '额度规则ID',
  `indicator_id` bigint(20) unsigned NOT NULL COMMENT '指标定义ID',
  `indicator_code` varchar(50) NOT NULL COMMENT '指标编码快照',
  `sort_no` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '排序',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_quota_rule_indicator` (`quota_rule_id`,`indicator_id`),
  KEY `idx_quota_rule_indicator_rule` (`quota_rule_id`),
  KEY `idx_quota_rule_indicator_indicator` (`indicator_id`),
  CONSTRAINT `fk_quota_rule_indicator_indicator` FOREIGN KEY (`indicator_id`) REFERENCES `indicator_definition` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_quota_rule_indicator_rule` FOREIGN KEY (`quota_rule_id`) REFERENCES `indicator_quota_rule` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='额度规则关联指标表';

#
# Data for table "indicator_quota_rule_indicator"
#


#
# Structure for table "rpa_execution_record"
#

CREATE TABLE `rpa_execution_record` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT 'Primary key',
  `execution_code` varchar(50) NOT NULL COMMENT '执行记录编码',
  `task_id` bigint(20) unsigned NOT NULL COMMENT '任务ID',
  `process_id` bigint(20) unsigned NOT NULL COMMENT '流程ID',
  `robot_id` bigint(20) unsigned NOT NULL COMMENT '机器人ID',
  `execute_status` int(11) NOT NULL COMMENT '执行状态：1执行中，2成功，3失败',
  `start_time` datetime NOT NULL COMMENT '开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `duration_seconds` int(10) unsigned DEFAULT NULL COMMENT '执行时长（秒）',
  `error_message` varchar(500) DEFAULT NULL COMMENT '错误信息',
  `log_content` longtext COMMENT 'Execution log',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `execution_log` text COMMENT '执行日志',
  `remark` text COMMENT '备注',
  `process_version_id` bigint(20) DEFAULT NULL,
  `process_version_no` int(11) DEFAULT NULL,
  `screenshot_url` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_rpa_execution_record_code` (`execution_code`),
  KEY `idx_rpa_execution_task_id` (`task_id`),
  KEY `idx_rpa_execution_process_id` (`process_id`),
  KEY `idx_rpa_execution_robot_id` (`robot_id`),
  CONSTRAINT `fk_rpa_execution_process` FOREIGN KEY (`process_id`) REFERENCES `rpa_process` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_rpa_execution_robot` FOREIGN KEY (`robot_id`) REFERENCES `rpa_robot` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_rpa_execution_task` FOREIGN KEY (`task_id`) REFERENCES `rpa_task` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=89 DEFAULT CHARSET=utf8mb4 COMMENT='RPA execution records';

#
