  `indicator_id` bigint(20) unsigned NOT NULL COMMENT '指标定义ID',
  `indicator_code` varchar(50) NOT NULL COMMENT '指标编码快照',
  `result_var_name` varchar(50) DEFAULT NULL COMMENT '指标结果变量名快照',
  `task_id` bigint(20) unsigned NOT NULL COMMENT '任务ID',
  `execution_id` bigint(20) unsigned NOT NULL COMMENT '执行记录ID',
  `taxpayer_id_no` varchar(32) NOT NULL COMMENT '纳税人识别号',
  `enterprise_name` varchar(120) NOT NULL COMMENT '企业名称',
  `result_type` varchar(20) NOT NULL DEFAULT 'NUMBER' COMMENT '结果类型：NUMBER/STRING/BOOLEAN/JSON',
  `result_value_decimal` decimal(24,6) DEFAULT NULL COMMENT '数值型结果',
  `result_value_text` varchar(500) DEFAULT NULL COMMENT '文本型结果',
  `result_value_json` json DEFAULT NULL COMMENT 'JSON型结果',
  `calculation_context` json DEFAULT NULL COMMENT '计算上下文快照',
  `source_data_ref` json DEFAULT NULL COMMENT '来源数据引用，如 analysisId/processingId/businessDataId',
  `status` int(11) NOT NULL DEFAULT '2' COMMENT '计算状态：1计算中，2成功，3失败',
  `error_message` varchar(500) DEFAULT NULL COMMENT '错误信息',
  `calculate_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '计算时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_indicator_result_indicator_execution` (`indicator_id`,`execution_id`),
  KEY `idx_indicator_result_code` (`indicator_code`),
  KEY `idx_indicator_result_task_id` (`task_id`),
  KEY `idx_indicator_result_execution_id` (`execution_id`),
  KEY `idx_indicator_result_taxpayer` (`taxpayer_id_no`),
  KEY `idx_indicator_result_enterprise` (`enterprise_name`),
  KEY `idx_indicator_result_calculate_time` (`calculate_time`),
  CONSTRAINT `fk_indicator_result_execution` FOREIGN KEY (`execution_id`) REFERENCES `rpa_execution_record` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_indicator_result_indicator` FOREIGN KEY (`indicator_id`) REFERENCES `indicator_definition` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_indicator_result_task` FOREIGN KEY (`task_id`) REFERENCES `rpa_task` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='指标计算结果表';

