CREATE TABLE `indicator_quota_result` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `quota_rule_id` bigint(20) unsigned NOT NULL COMMENT '额度规则ID',
  `branch_id` bigint(20) unsigned DEFAULT NULL COMMENT '命中的分支ID',
  `execution_id` bigint(20) unsigned DEFAULT NULL COMMENT '同批次执行记录ID；混合最近指标结果时为空',
  `taxpayer_id_no` varchar(32) NOT NULL COMMENT '纳税人识别号',
  `enterprise_name` varchar(120) NOT NULL COMMENT '企业名称',
  `indicator_result_ids` json DEFAULT NULL COMMENT '本次使用的指标结果ID列表',
  `indicator_values` json DEFAULT NULL COMMENT '本次使用的指标变量和值',
  `result_var_name` varchar(50) NOT NULL COMMENT '额度结果变量名快照',
  `result_type` varchar(20) NOT NULL DEFAULT 'NUMBER' COMMENT '结果类型：NUMBER/STRING/BOOLEAN/JSON',
  `calculated_value_decimal` decimal(24,6) DEFAULT NULL COMMENT '额度数值结果',
  `calculated_value_text` varchar(500) DEFAULT NULL COMMENT '额度文本结果',
  `calculated_value_json` json DEFAULT NULL COMMENT '额度JSON结果',
  `output_data` json DEFAULT NULL COMMENT '渲染后的输出数据',
  `status` int(11) NOT NULL DEFAULT '2' COMMENT '计算状态：1计算中，2成功，3失败',
  `error_message` varchar(500) DEFAULT NULL COMMENT '错误信息',
  `calculate_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '计算时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_quota_result_rule` (`quota_rule_id`),
  KEY `idx_quota_result_branch` (`branch_id`),
  KEY `idx_quota_result_execution` (`execution_id`),
  KEY `idx_quota_result_taxpayer` (`taxpayer_id_no`),
  KEY `idx_quota_result_enterprise` (`enterprise_name`),
  KEY `idx_quota_result_calculate_time` (`calculate_time`),
  CONSTRAINT `fk_quota_result_branch` FOREIGN KEY (`branch_id`) REFERENCES `indicator_quota_rule_branch` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_quota_result_execution` FOREIGN KEY (`execution_id`) REFERENCES `rpa_execution_record` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_quota_result_rule` FOREIGN KEY (`quota_rule_id`) REFERENCES `indicator_quota_rule` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='指标额度计算结果表';

