  CONSTRAINT `fk_data_collection_task` FOREIGN KEY (`task_id`) REFERENCES `rpa_task` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COMMENT='Collected raw data';

